"""Record agent visual draft, never rewrite the weak labels or raw evaluation."""
import json
import hashlib
from pathlib import Path
from collections import Counter
ROOT=Path(__file__).resolve().parents[1]

GEOMETRY={309:'GND text aligns with connector ground row; nearest selects lower mounting location. Weak target visually plausible, independent pin identity unverified.',4309:'Number 20 lies between adjacent output rows; weak target on second OUT row is visually plausible. Typography offset warrants geometry investigation, not automatic correction.',4310:'SENSE text lies beside right-side pin 2; nearest chooses bottom GND endpoint. Weak target visually aligns with SENSE row.',5497:'CV text on left-side pin 5; nearest chooses bottom GND pin 1. Side-aware geometry is a plausible correction.'}
OCR={2097:'Actual OCR token combines printed number 4 and name DO. Splitting roles is plausible; exact source text match does not establish wrong OCR recognition.',4202:'Token 234 spans three printed connector numbers 2,3,4. Local segmentation could restore distinct tokens; weak owner remains unverified.',4210:'Token 234 spans three printed connector numbers 2,3,4. Local segmentation could restore distinct tokens; weak owner remains unverified.',4304:'Token 234 spans three printed connector numbers 2,3,4. Local segmentation could restore distinct tokens; weak owner remains unverified.',6269:'Visible label IO5 is transcribed as 105, also in weak annotation. Recognition and pin-name role deserve independent review; not a valid numeric pin label.',6270:'Visible label IO0 is transcribed as 100, also in weak annotation. Recognition and pin-name role deserve independent review; not a valid numeric pin label.',7167:'Token B is a partial alphabetic connector label near B8/B9; local recognition/segmentation investigation needed, no verified corrected transcription.'}
UNKNOWN={333:'Number 3 is small and between rows; contact sheet alone cannot establish which physical pin owns the glyph.',6373:'Weak number 13 and LDO rows are inconsistent in local view; actual glyph/ownership cannot be confidently adjudicated.'}
ROLE={1659:'Visible component model STM32F103C8T6 is stored as pin_number.',1709:'Visible capacitor value 0.1uF is stored as another component pin_number.',1718:'Visible component designator U1 is stored as pin_number.',1732:'Visible component model RT9193-33 is stored as pin_number.',1734:'Visible component label USB is stored as pin_number.',1918:'Visible nearby capacitor designator C5 is stored as IC pin_number.',2102:'Visible resistor role RSEL2 is stored as connector pin_number.',2105:'Visible capacitor role CCDT is stored as connector pin_number.',2237:'VBUS text is on electrical pin 1; weak target is mounting pin 7. Nearest is visually more plausible.',3743:'Merged supply labels 1V1/3V3 are stored as pin_number.',5490:'Visible component model LM2576S-5.0/TR is stored as pin_number.',6243:'Visible nearby capacitor value 100nF is stored as pin_number.',7271:'Visible ADC1 signal label is stored as pin_number; weak target drifts to another row.',7284:'Visible VMAIN supply label plus number 11 is stored as pin_number; merged text and ownership unclear.'}

def main():
    path=ROOT/'output/ablation/hard56-review-draft.json'; data=json.loads(path.read_text(encoding='utf-8'))
    audit_path=ROOT/'output/ablation/pin-token-residual-audit.json'
    audit=json.loads(audit_path.read_text(encoding='utf-8'))
    original=audit['variants']['logistic']['validation']; assert original['hard']==56
    data['raw56_HRR_unchanged']=original['HRR']
    data['original_logistic_validation']=original
    data['original_gate_protocol']=audit['protocol']
    data['residual_audit_sha256']=hashlib.sha256(audit_path.read_bytes()).hexdigest()
    for e in data['entries']:
        i=e['index']; e['agent_visual_review']=True; e['review_evidence']='All four rendered contact sheets inspected using view_image; agent visual draft only.'
        if i in GEOMETRY: category,note='geometry-fixable',GEOMETRY[i]
        elif i in OCR: category,note='ocr-fixable',OCR[i]
        elif i in UNKNOWN: category,note='unknown',UNKNOWN[i]
        elif i in ROLE: category,note='label-ambiguous',ROLE[i]
        elif sum((a-b)**2 for a,b in zip(e['nearest_point'],e['weak_target_point']))<25:
            category,note='label-ambiguous','Compared weak endpoints are within 5 pixels on visually the same stroke/row. Pin identity or endpoint duplication is unresolved; do not count as confidently correctable geometry.'
        else: category,note='label-ambiguous','Weak target is on a neighboring row inconsistent with the printed token position, or text role conflicts with pin-number field. Exact OCR-to-annotation string match does not validate pin ownership.'
        e['category']=category; e['note']=note; e['human_reviewed']=False; e['independent_truth_confirmed']=False
    data['category_counts']=dict(Counter(e['category'] for e in data['entries'])); data['candidate_missing_observed']=0
    data['limitations']=['No human adjudication; all 56 retained, no post-score removal.','Candidate-missing is impossible for the weak target in this conditioned top8 cache; real candidate recall is not assessed.','Exact token text already matches weak annotation; OCR segmentation/recognition proposals require independent glyph review.','No reviewed-correctable HRR is computed because independent corrected labels do not exist.','Geometry/OCR fixable classes denote investigation hypotheses, not confirmed recoverable errors.']
    path.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
    payload=json.dumps(data['entries'],ensure_ascii=False).replace('</','<\\/')
    html='''<!doctype html><meta charset="utf-8"><title>Hard56 draft review</title><style>body{font:16px sans-serif;max-width:1200px;margin:auto}article{border:1px solid #ddd;padding:12px;margin:16px 0}img{width:410px;float:left;margin:0 20px 10px 0}article:after{content:"";display:block;clear:both}textarea{width:55%;height:90px}button,select{padding:8px}</style><h1>56 fixed development cases — agent draft</h1><p>Not human-reviewed ground truth. Blue: OCR box; red N: nearest; green W: weak source target. All 56 are retained. Editing here creates separate reviewer notes only; does not update models, weak labels, scores or the frozen draft. Reviewed-correctable HRR remains null.</p><button onclick="save()">Export separate reviewer notes JSON</button><div id="cases"></div><script>const rows=PAYLOAD; const key='hard56-review-notes-v1';let notes=JSON.parse(localStorage.getItem(key)||'{}');const cats=['unknown','geometry-fixable','ocr-fixable','candidate-missing','label-ambiguous']; for(const r of rows){const a=document.createElement('article');const im=document.createElement('img'); im.src='hard56-review/'+r.crop.split('/').pop();a.append(im);const h=document.createElement('h3');h.textContent=r.review_order+': '+r.page+' / '+r.token.text+' / index '+r.index;a.append(h);const p=document.createElement('p');p.textContent='Agent draft: '+r.category+' — '+r.note;a.append(p);const s=document.createElement('select');for(const c of cats){const o=document.createElement('option');o.value=c;o.textContent=c;s.append(o)}s.value=(notes[r.index]||{}).category||'unknown';a.append(s);a.append(document.createElement('br'));const t=document.createElement('textarea');t.placeholder='Independent reviewer evidence, transcription, owner, uncertainty';t.value=(notes[r.index]||{}).note||'';a.append(t);const change=()=>{notes[r.index]={category:s.value,note:t.value,index:r.index,page:r.page};localStorage.setItem(key,JSON.stringify(notes))};s.onchange=t.oninput=change;document.querySelector('#cases').append(a)} function save(){const blob=new Blob([JSON.stringify({status:'reviewer-notes-unverified',raw_hard_count:56,reviewed_correctable_HRR:null,notes},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='hard56-reviewer-notes.json';a.click();URL.revokeObjectURL(a.href)}</script>'''.replace('PAYLOAD',payload)
    (ROOT/'output/ablation/hard56-review.html').write_text(html,encoding='utf-8')
    counts=data['category_counts']
    doc=f'''# Hard56 代理图像审查草稿\n\n本轮固定审查全部 56 个开发验证 hard case，未根据纠正结果删样本。已逐一通过四张联系表核对实际像素。审查是 AI 代理草稿，不是人工审核或独立真值。\n\n分类统计：{json.dumps(counts,ensure_ascii=False)}。geometry-fixable 与 ocr-fixable 是待验证的可纠正假设；并非已确认可恢复样本。其余 label-ambiguous 包括弱 pinNumber 字段放入器件型号、位号、容值，以及相邻行引用偏移或近重合端点。\n\n原始 HRR 保持 **9/56 = 16.07%**，原测试门槛不变。reviewed-correctable HRR 为 **null**，因为尚无独立人工修正真值。没有训练、运行时改动或 Freeze-A/B 数据使用。\n\n## 关键观测\n\n0016 的数字 12/13/17/10 多次弱关联到下一行；0043 将 STM32F103C8T6、0.1uF、U1、RT9193-33、USB 标成 pin_number；0064 的 VBUS 弱关联到安装脚 7，而印刷文字实际在电气脚 1 行。不能让关联模型追随这些未审核的目标。\n\n潜在几何难例包括 0005 GND、0108 SENSE、0128 CV 的跨边最近端点，以及 0108 数字 20 的行间字形位置。潜在 OCR 工作包括连接器合并 token 234、4 DO 和 0150 的 IO5/IO0 被转录为 105/100。当前输入 token 已与弱源原文精确匹配；此处没有把最近端点错误直接称作 OCR 错。\n\n原缓存要求弱目标位于 top8，故 candidate-missing 计数 0 是筛选条件，不能据此断言真实候选召回完整。\n\n## 审核交付\n\n- 明细：`output/ablation/hard56-review-draft.json`。\n- 联系表：`output/ablation/hard56-review/contact-1.png` 至 `contact-4.png`。\n- 交互入口：`output/ablation/hard56-review.html`。支持保存浏览器本地审核备注、导出单独 JSON；不修改草稿、训练标签或评分。人工审核时需确认文字转录、文字角色、实际所属元件、端点身份，再建立独立修正标签。\n\n父实验依然以 raw56 为原分母。代理草稿不能用于宣称新的 HRR 或竞争分数。\n'''
    (ROOT/'docs/HARD56_REVIEW_DRAFT.md').write_text(doc,encoding='utf-8');print(json.dumps(counts))
if __name__=='__main__': main()
